2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (canonical region). The postcode is preferred: a 4-digit
7	 * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
8	 * fixes the region directly, which disambiguates cities that share a name. Only when the
9	 * postcode is absent or in no known range does it fall back to the fixed city-to-region
10	 * table. Kept out of {@link OwnerMapper} so MapStruct does not mistake the helper for an
11	 * implicit mapping method and apply it to every string property.
12	 */
13	public final class Locality {
14	
15	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
18	
19	    /** Region -> inclusive 4-digit postcode range {low, high}. */
20	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
21	        "NSW", new int[] {2000, 2099},
22	        "VIC", new int[] {3000, 3099},
23	        "QLD", new int[] {4000, 4099});
24	
25	    private Locality() {
26	    }
27	
28	    /**
29	     * The canonical region, preferring the postcode range and falling back to the
30	     * city-to-region table. Returns "UNKNOWN" when neither resolves a region.
31	     */
32	    public static String of(String city, String postcode) {
33	        String byPostcode = regionForPostcode(postcode);
34	        return byPostcode != null ? byPostcode : of(city);
35	    }
36	
37	    /** The canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
38	    public static String of(String city) {
39	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
40	    }
41	
42	    /**
43	     * The region whose range contains {@code postcode}, or {@code null} when the postcode
44	     * is absent, non-numeric, or in no known range.
45	     */
46	    private static String regionForPostcode(String postcode) {
47	        if (postcode == null || postcode.isBlank()) {
48	            return null;
49	        }
50	        int value;
51	        try {
52	            value = Integer.parseInt(postcode.trim());
53	        }
54	        catch (NumberFormatException ex) {
55	            return null;
56	        }
57	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
58	            int[] range = entry.getValue();
59	            if (value >= range[0] && value <= range[1]) {
60	                return entry.getKey();
61	            }
62	        }
